@frappe.whitelist(methods=['POST'])
def create_user(employee, email=None, create_user_permission=0):
    emp = frappe.get_doc('Employee', employee)
    if emp.user_id: frappe.throw(_('already has a linked user'))
    user = frappe.new_doc('User'); user.update({...}); user.append_roles('Employee'); user.insert()
    emp.user_id = user.name; emp.save()
    return user.name

@frappe.whitelist()
def get_children(doctype, parent=None, company=None, is_root=False, is_tree=False):
    filters = [['status', '=', 'Active']]
    if parent and company and parent != company: filters.append(['reports_to', '=', parent])
    return frappe.get_list(doctype, fields=['name as value', 'employee_name as title'], filters=filters)
